SELECT      c.id AS "Id do curso",     c.fullname AS "Curso",     COUNT(ue.id) AS "Total de usuários inscritos",     COUNT(CASE WHEN cmc.completionstate = 2 THEN cmc.userid END) AS "Total de usuários concluídos",     ROUND(         (COUNT(CASE WHEN cmc.completionstate = 2 THEN cmc.userid END) / NULLIF(COUNT(ue.id), 0)) * 100,          2     ) AS "% Índice de conclusão" FROM      mdl_course c LEFT JOIN      mdl_enrol e ON c.id = e.courseid LEFT JOIN      mdl_user_enrolments ue ON e.id = ue.enrolid LEFT JOIN      mdl_course_modules_completion cmc ON cmc.userid = ue.userid AND cmc.coursemoduleid IN (         SELECT id FROM mdl_course_modules WHERE course = c.id     ) WHERE      c.visible = 1 GROUP BY      c.id ORDER BY      "% Índice de conclusão" DESC LIMIT 5;
